+/// The start of the frontmatter line carrying the skill's checksum, under
+/// `metadata`.
+const CHECKSUM_PREFIX: &str = "  checksum: ";
+
+/// Splits a `SKILL.md` into its content without the frontmatter's
+/// `checksum` line, and the checksum that line carries — `None` for a
+/// skill rendered before checksums.
+fn split_checksum(contents: &str) -> Option<(String, String)> {
+    if !contents.starts_with("---") {
+        return None;
+    }
+    let mut start = contents.find('\n')? + 1;
+    for line in contents[start..].split_inclusive('\n') {
+        if line.trim_end() == "---" {
+            break;
+        }
+        if let Some(value) = line.strip_prefix(CHECKSUM_PREFIX) {
+            let unstamped = format!("{}{}", &contents[..start], &contents[start + line.len()..]);
+            return Some((unstamped, value.trim().trim_matches('"').to_string()));
+        }
+        start += line.len();
+    }
